<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('design.view_assigned');$pdo=staff_db();$staff=current_staff();$main=customer_db();
$s=$pdo->prepare("SELECT * FROM design_assignments WHERE assigned_to=? ORDER BY assigned_at DESC");$s->execute([$staff['id']]);$assign=$s->fetchAll();$map=[];
if($main&&$assign){$ids=array_values(array_filter(array_map(fn($x)=>(int)$x['design_id'],$assign)));if($ids){$q=$main->prepare("SELECT * FROM designs WHERE id IN(".implode(',',array_fill(0,count($ids),'?')).")");$q->execute($ids);foreach($q->fetchAll() as $d)$map[$d['id']]=$d;}}
$pageTitle='Assigned Designs';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Work</p><h1>Assigned designs</h1></div><a class="btn" href="<?= h(ideare_root_url('designer/index.php')) ?>">Open Cabinet Designer</a></div><div class="task-grid"><?php foreach($assign as $a):$d=$map[$a['design_id']]??null;?><article class="staff-panel task-card"><div class="rowtop"><span class="pill"><?= h($a['assignment_type']) ?></span><span class="pill"><?= h(str_replace('_',' ',$a['status'])) ?></span></div><h2><?= h($a['design_code']) ?></h2><p><b><?= h($d['design_name']??'Design record unavailable') ?></b></p><?php if($d):?><p class="muted"><?= h($d['customer_name']?:'No customer') ?> · <?= h($d['room_type']?:'No room') ?> · <?= money($d['estimated_price']) ?></p><?php endif;?><p><?= h($a['notes']?:'') ?></p></article><?php endforeach;?></div></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
